class MainActivity:Activity(){
 data class F(var x:Float,var hp:Int,val max:Int,val boss:Boolean=false,var hit:Int=-1,var flash:Float=0f)
 data class P(val x:Float,var got:Boolean=false); data class H(val x:Float,val w:Float); enum class A{JUMP,WHACK}
 override fun onCreate(b:Bundle?){super.onCreate(b);requestWindowFeature(Window.FEATURE_NO_TITLE);window.setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);window.decorView.systemUiVisibility=5894;setContentView(Game())}
 inner class Game:View(this@MainActivity){
  val p=Paint(Paint.ANTI_ALIAS_FLAG);val birds=mutableListOf<F>();val cans=mutableListOf<P>();val junk=mutableListOf<H>();val world=5600f
  var px=220f;var py=0f;var vy=0f;var gy=0f;var cam=0f;var face=1;var joy:Int?=null;var jx=0f;var jy=0f;var score=0;var hp=100;var beers=0;var start=false;var dead=false;var win=false;var atk=0f;var atkId=0;var hurt=0f;var t=0f;var last=System.nanoTime();var msg="";var msgT=0f;var combo=0;var comboT=0f;var best=0;var wave=1;var bossIntro=false;var rage=false
  init{reset()}
  fun reset(){px=220f;py=0f;vy=0f;cam=0f;score=0;hp=100;beers=0;dead=false;win=false;atk=0f;hurt=0f;t=0f;combo=0;comboT=0f;best=0;wave=1;bossIntro=false;rage=false;birds.clear();birds+=F(900f,2,2);birds+=F(1420f,2,2);birds+=F(2050f,3,3);birds+=F(2700f,3,3);birds+=F(3350f,4,4);birds+=F(4550f,10,10,true);cans.clear();cans+=P(1180f);cans+=P(2420f);cans+=P(3600f);junk.clear();junk+=H(1740f,110f);junk+=H(3020f,105f);junk+=H(3920f,115f)}
  override fun onDraw(c:Canvas){val n=System.nanoTime();val dt=((n-last)/1e9f).coerceAtMost(.04f);last=n;gy=height*.77f;if(py==0f)py=gy;if(start&&!dead&&!win)update(dt);scene(c);hud(c);controls(c);overlay(c);postInvalidateOnAnimation()}
  fun update(d:Float){t+=d;comboT=max(0f,comboT-d);if(comboT<=0)combo=0;val m=if(abs(jx)<.14f)0f else jx;if(m!=0f){face=if(m>0)1 else -1;px=(px+m*430*d).coerceIn(55f,world-80)};vy+=1550*d;py+=vy*d;if(py>gy){py=gy;vy=0f};atk=max(0f,atk-d);hurt=max(0f,hurt-d);msgT=max(0f,msgT-d);cam+=(px-width*.37f-cam)*min(1f,d*7);cam=cam.coerceIn(0f,max(0f,world-width));wave=if(px<1800)1 else if(px<3700)2 else 3
   for(b in birds){b.flash=max(0f,b.flash-d);if(b.hp<=0)continue;val dx=px-b.x;if(abs(dx)<if(b.boss)800 else 520){val fast=b.boss&&b.hp<=b.max/2;b.x+=(if(dx>0)1 else -1)*(if(fast)180 else if(b.boss)115 else 88)*d};if(atk>0&&b.hit!=atkId){val sd=(b.x-px)*face;if(sd in 15f..195f&&py>gy-165){b.hp--;b.hit=atkId;b.flash=.12f;b.x+=face*(if(b.boss)45 else 82);combo++;comboT=1.45f;best=max(best,combo);score+=(if(b.boss)250 else 100)*(1+(combo-1)/3);say(if(combo>=3)"$combo HIT COMBO — BAD DECISIONS MULTIPLIED" else "BONK.",.7f);if(b.boss&&b.hp<=b.max/2&&!rage&&b.hp>0){rage=true;say("ALPHA FLAMINGO HAS ENTERED FULL KAREN MODE.",1.7f)};if(b.hp<=0)score+=if(b.boss)1800 else 300}};if(abs(b.x-px)<if(b.boss)95 else 62&&py>gy-95&&hurt<=0){hp=max(0,hp-if(b.boss)18 else 10);hurt=.75f;combo=0;px+=if(dx>0)-105 else 105;say("THIS WAS A TERRIBLE PLAN.",.9f);if(hp<=0)dead=true}}
   for(h in junk)if(abs(px-h.x)<h.w/2+28&&py>gy-72&&hurt<=0){hp=max(0,hp-8);hurt=.7f;px+=if(px<h.x)-100 else 100;if(hp<=0)dead=true};for(q in cans)if(!q.got&&abs(q.x-px)<68&&py>gy-130){q.got=true;beers++;hp=min(100,hp+25);score+=200;say("COLD ONE ACQUIRED. +25 QUESTIONABLE HEALTH.",1.2f)};val boss=birds.last();if(!bossIntro&&px>4050&&boss.hp>0){bossIntro=true;say("BOSS FIGHT: ALPHA FLAMINGO",2f)};if(boss.hp<=0&&px>5100)win=true}
  fun say(s:String,d:Float){msg=s;msgT=d}
  fun scene(c:Canvas){val sky=LinearGradient(0f,0f,0f,gy,Color.rgb(55,62,137),Color.rgb(245,113,99),Shader.TileMode.CLAMP);p.shader=sky;c.drawRect(0f,0f,width.toFloat(),gy,p);p.shader=null;p.color=Color.rgb(255,181,48);c.drawCircle(width*.68f,gy*.43f,height*.085f,p);p.color=Color.rgb(42,48,85);for(i in 0..10){val x=i*width/9f-(cam*.08f%160);c.drawRect(x,gy*.43f,x+12,gy*.72f,p);c.drawCircle(x+6,gy*.42f,38f,p)};water(c);palms(c);house(c);fence(c);p.color=Color.rgb(214,173,124);c.drawRect(0f,gy,width.toFloat(),gy+height*.075f,p);p.color=Color.rgb(28,104,67);c.drawRect(0f,gy+height*.075f,width.toFloat(),height.toFloat(),p);sign(c,650f,"POOL NOODLE\nPANIC");sign(c,3150f,"SAME MESS\nDIFFERENT DAY");for(h in junk)hazard(c,h);for(q in cans)if(!q.got)can(c,q);for(b in birds)if(b.hp>0)bird(c,b);man(c);sign(c,5250f,"BACKYARD\nEXIT")}
  fun water(c:Canvas){p.color=Color.rgb(27,99,143);c.drawRect(0f,gy*.58f,width.toFloat(),gy*.73f,p);p.color=Color.rgb(255,143,113);for(i in 0..8)c.drawRect(i*180f-(cam*.15f%180),gy*.64f,i*180f+95-(cam*.15f%180),gy*.645f,p);p.color=Color.rgb(21,47,52);val ax=width*.76f-(cam*.05f%400);c.drawOval(ax,gy*.66f,ax+105,gy*.70f,p);p.color=Color.YELLOW;c.drawCircle(ax+78,gy*.675f,4f,p)}
  fun palms(c:Canvas){for(i in 0..5){val x=i*330f-((cam*.22f)%330)-100;p.color=Color.rgb(72,49,39);p.strokeWidth=18f;c.drawLine(x,gy*.65f,x+35,gy*.22f,p);p.color=Color.rgb(15,75,55);for(a in -2..2){val yy=gy*.22f;c.drawOval(x+35+a*8-70,yy-18-abs(a)*8,x+35+a*8+70,yy+18+abs(a)*5,p)}}}
  fun house(c:Canvas){val x=150f-(cam*.35f%1900);p.color=Color.rgb(89,91,111);c.drawRect(x,gy*.45f,x+430,gy*.69f,p);p.color=Color.rgb(52,45,52);val path=Path();path.moveTo(x-30,gy*.46f);path.lineTo(x+210,gy*.32f);path.lineTo(x+465,gy*.46f);path.close();c.drawPath(path,p);p.color=Color.rgb(255,205,85);for(i in 0..5)c.drawCircle(x+45+i*65,gy*.48f,5f,p)}
  fun fence(c:Canvas){p.color=Color.rgb(128,88,62);var x=-((cam*.62f)%78)-78;while(x<width+78){c.drawRect(x,gy*.53f,x+62,gy*.73f,p);val q=Path();q.moveTo(x,gy*.53f);q.lineTo(x+31,gy*.49f);q.lineTo(x+62,gy*.53f);q.close();c.drawPath(q,p);x+=78}}
  fun sign(c:Canvas,xw:Float,s:String){val x=xw-cam;if(x !in -180f..width+180f)return;p.color=Color.rgb(78,48,29);c.drawRect(x-6,gy-145,x+6,gy,p);p.color=Color.rgb(231,211,168);c.drawRect(x-105,gy-225,x+105,gy-140,p);p.color=Color.rgb(36,31,32);p.typeface=Typeface.DEFAULT_BOLD;p.textAlign=Paint.Align.CENTER;p.textSize=20f;val ls=s.split("\n");ls.forEachIndexed{i,v->c.drawText(v,x,gy-192+i*27,p)};p.textAlign=Paint.Align.LEFT}
  fun hazard(c:Canvas,h:H){val x=h.x-cam;if(x !in -120f..width+120)return;p.color=Color.rgb(178,36,38);c.drawRoundRect(x-50,gy-58,x+50,gy+4,8f,8f,p);p.color=Color.WHITE;c.drawRect(x-53,gy-66,x+53,gy-52,p);p.color=Color.rgb(90,24,24);c.drawRect(x-38,gy-45,x+38,gy-30,p)}
  fun can(c:Canvas,q:P){val x=q.x-cam;if(x !in -80f..width+80)return;val y=gy-62+sin(t*4+q.x*.01).toFloat()*6;p.color=Color.argb(80,255,224,60);c.drawCircle(x,y,40,p);p.color=Color.rgb(226,226,220);c.drawRoundRect(x-18,y-32,x+18,y+32,5f,5f,p);p.color=Color.rgb(35,93,184);c.drawRect(x-18,y-10,x+18,y+14,p);p.color=Color.YELLOW;p.textAlign=Paint.Align.CENTER;p.typeface=Typeface.DEFAULT_BOLD;p.textSize=11f;c.drawText("BEER",x,y+5,p);p.textAlign=Paint.Align.LEFT}
  fun man(c:Canvas){if(hurt>0&&(hurt*12).toInt()%2==0)return;val x=px-cam;val y=py;p.color=Color.rgb(235,169,115);c.drawRect(x-28,y-7,x-9,y+43,p);c.drawRect(x+9,y-7,x+28,y+43,p);p.color=Color.rgb(26,86,175);c.drawRect(x-38,y-49,x+38,y+5,p);p.color=Color.WHITE;c.drawRect(x-35,y-112,x+35,y-47,p);p.color=Color.rgb(28,135,72);c.drawCircle(x,y-80,13,p);p.color=Color.rgb(235,169,115);c.drawCircle(x,y-148,37,p);p.color=Color.rgb(105,59,27);c.drawRect(x-42,y-179,x+28,y-159,p);c.drawRect(x-42,y-162,x-27,y-111,p);p.color=Color.rgb(222,189,126);c.drawRect(x-39,y-184,x+30,y-169,p);p.color=Color.rgb(35,35,38);c.drawRect(x-29,y-154,x-3,y-143,p);c.drawRect(x+3,y-154,x+29,y-143,p);p.color=Color.rgb(35,35,38);c.drawRect(x-34,y+39,x-4,y+47,p);c.drawRect(x+4,y+39,x+34,y+47,p);p.strokeWidth=21;p.strokeCap=Paint.Cap.ROUND;p.color=Color.rgb(32,154,255);val sx=x+face*26;val sy=y-90;if(atk>0){val z=(1-atk/.2f).coerceIn(0f,1f);val deg=if(face>0)-70+z*105 else 250-z*105;val r=Math.toRadians(deg.toDouble());c.drawLine(sx,sy,sx+cos(r).toFloat()*172,sy+sin(r).toFloat()*172,p)}else c.drawLine(sx,sy,x+face*82,y-132,p)}
  fun bird(c:Canvas,b:F){val x=b.x-cam;if(x !in -190f..width+190)return;val s=if(b.boss)1.55f else 1f;val y=gy-86*s;p.color=if(b.flash>0)Color.WHITE else if(b.boss&&b.hp<=b.max/2)Color.rgb(205,31,68) else Color.rgb(239,62,116);c.drawOval(x-48*s,y-30*s,x+43*s,y+31*s,p);val wing=Path();wing.moveTo(x-10*s,y-12*s);wing.lineTo(x+20*s,y-65*s);wing.lineTo(x+35*s,y-8*s);wing.close();c.drawPath(wing,p);p.style=Paint.Style.STROKE;p.strokeWidth=14*s;c.drawLine(x+25*s,y-20*s,x+32*s,y-94*s,p);p.style=Paint.Style.FILL;c.drawCircle(x+49*s,y-112*s,25*s,p);p.color=Color.rgb(25,25,25);val beak=Path();beak.moveTo(x+68*s,y-113*s);beak.lineTo(x+105*s,y-126*s);beak.lineTo(x+73*s,y-101*s);beak.close();c.drawPath(beak,p);p.color=Color.YELLOW;c.drawCircle(x+54*s,y-118*s,7*s,p);p.color=Color.RED;c.drawCircle(x+56*s,y-119*s,3*s,p);p.strokeWidth=8*s;p.color=Color.rgb(45,30,40);c.drawLine(x-17*s,y+24*s,x-23*s,gy+25,p);c.drawLine(x+12*s,y+24*s,x+21*s,gy+25,p);if(b.boss){p.textAlign=Paint.Align.CENTER;p.typeface=Typeface.DEFAULT_BOLD;p.textSize=23f;p.color=Color.YELLOW;c.drawText("ALPHA FLAMINGO",x,y-170,p);p.color=Color.argb(190,0,0,0);c.drawRect(x-90,y-158,x+90,y-143,p);p.color=Color.RED;c.drawRect(x-90,y-158,x-90+180*b.hp.toFloat()/b.max,y-143,p);p.textAlign=Paint.Align.LEFT}}
  fun hud(c:Canvas){val pad=height*.03f;p.color=Color.argb(205,9,13,24);c.drawRoundRect(pad,pad,width*.34f,pad+height*.095f,10f,10f,p);p.color=Color.rgb(255,204,43);p.typeface=Typeface.DEFAULT_BOLD;p.textSize=height*.035f;c.drawText("HOLD MY BEER",pad*1.7f,pad+height*.04f,p);p.color=Color.rgb(20,38,57);c.drawRect(pad*1.7f,pad+height*.057f,width*.31f,pad+height*.079f,p);p.color=if(hp>35)Color.rgb(54,210,57) else Color.RED;c.drawRect(pad*1.7f,pad+height*.057f,pad*1.7f+(width*.31f-pad*1.7f)*hp/100f,pad+height*.079f,p);p.textAlign=Paint.Align.CENTER;p.textSize=height*.048f;p.color=Color.rgb(255,209,45);c.drawText("FLORIDA MAN",width/2f,pad+height*.043f,p);p.textSize=height*.024f;p.color=Color.WHITE;c.drawText("POOL NOODLE PANIC • LEVEL 1 • WAVE $wave/3",width/2f,pad+height*.074f,p);p.textAlign=Paint.Align.RIGHT;p.textSize=height*.032f;c.drawText("SCORE $score",width-pad*1.5f,pad+height*.034f,p);p.textSize=height*.025f;p.color=Color.rgb(255,207,47);c.drawText("COLD ONES x $beers",width-pad*1.5f,pad+height*.068f,p);if(combo>=2){p.textAlign=Paint.Align.CENTER;p.textSize=height*.044f;p.color=Color.rgb(255,117,34);c.drawText("COMBO x$combo",width*.69f,height*.16f,p)};if(msgT>0&&start&&!dead&&!win){p.textAlign=Paint.Align.CENTER;p.textSize=min(27f,height*.032f);p.color=Color.WHITE;c.drawText(msg,width/2f,height*.225f,p)};p.textAlign=Paint.Align.LEFT}
  fun controls(c:Canvas){val r=min(height*.085f,78f);val y=height-r-height*.035f;val jr=min(height*.115f,96f);val cx=max(96f,height*.16f);val cy=height-max(82f,height*.14f);p.color=Color.argb(110,5,10,18);c.drawCircle(cx,cy,jr,p);p.color=Color.argb(220,28,40,55);c.drawCircle(cx+jx*jr*.58f,cy+jy*jr*.58f,jr*.46f,p);button(c,width-r-height*.035f-r*2.25f,y,r,"JUMP");button(c,width-r-height*.035f,y,r,"WHACK")}
  fun button(c:Canvas,x:Float,y:Float,r:Float,s:String){p.color=Color.argb(150,5,10,18);c.drawCircle(x,y,r,p);p.color=Color.WHITE;p.typeface=Typeface.DEFAULT_BOLD;p.textAlign=Paint.Align.CENTER;p.textSize=r*.32f;c.drawText(s,x,y+p.textSize*.34f,p);p.textAlign=Paint.Align.LEFT}
  fun overlay(c:Canvas){if(start&&!dead&&!win)return;p.color=Color.argb(210,4,8,18);c.drawRect(0f,height*.24f,width.toFloat(),height*.70f,p);p.textAlign=Paint.Align.CENTER;p.typeface=Typeface.DEFAULT_BOLD;if(!start){p.textSize=height*.07f;p.color=Color.rgb(255,205,39);c.drawText("FLORIDA MAN",width/2f,height*.38f,p);p.textSize=height*.045f;p.color=Color.WHITE;c.drawText("LEGENDARY BAD DECISIONS",width/2f,height*.45f,p);p.textSize=height*.035f;p.color=Color.rgb(255,112,46);c.drawText("POOL NOODLE PANIC",width/2f,height*.53f,p);p.textSize=height*.027f;p.color=Color.WHITE;c.drawText("TAP TO START • SURVIVE 3 WAVES • DEFEAT THE ALPHA FLAMINGO",width/2f,height*.61f,p)}else if(dead){p.textSize=height*.07f;p.color=Color.rgb(255,80,65);c.drawText("WELL, THAT ESCALATED.",width/2f,height*.44f,p);p.textSize=height*.035f;p.color=Color.WHITE;c.drawText("BEST COMBO $best • TAP TO TRY AGAIN",width/2f,height*.55f,p)}else{p.textSize=height*.066f;p.color=Color.YELLOW;c.drawText("BACKYARD SURVIVED. SOMEHOW.",width/2f,height*.43f,p);p.textSize=height*.034f;p.color=Color.WHITE;c.drawText("SCORE $score • BEST COMBO $best • COLD ONES $beers/3",width/2f,height*.54f,p);c.drawText("TAP TO RUN IT AGAIN",width/2f,height*.62f,p)};p.textAlign=Paint.Align.LEFT}
  fun jump(){if(py>=gy-4)vy=-720f};fun whack(){if(atk<=0){atkId++;atk=.2f}}
  override fun onTouchEvent(e:MotionEvent):Boolean{when(e.actionMasked){0,5->{val i=e.actionIndex;val id=e.getPointerId(i);val x=e.getX(i);val y=e.getY(i);if(!start){start=true;last=System.nanoTime();return true};if(dead||win){reset();start=true;last=System.nanoTime();return true};val cx=max(96f,height*.16f);val cy=height-max(82f,height*.14f);val jr=min(height*.115f,96f);if(joy==null&&hypot(x-cx,y-cy)<=jr*1.45f){joy=id;setJoy(x,y)}else{val r=min(height*.085f,78f);val by=height-r-height*.035f;val wx=width-r-height*.035f;val jumpx=wx-r*2.25f;if(hypot(x-wx,y-by)<=r*1.22)whack() else if(hypot(x-jumpx,y-by)<=r*1.22)jump()}};2->{joy?.let{id->val i=e.findPointerIndex(id);if(i>=0)setJoy(e.getX(i),e.getY(i))}};1,6->{val id=e.getPointerId(e.actionIndex);if(id==joy){joy=null;jx=0f;jy=0f}};3->{joy=null;jx=0f;jy=0f}};return true}
  fun setJoy(x:Float,y:Float){val cx=max(96f,height*.16f);val cy=height-max(82f,height*.14f);val r=min(height*.115f,96f);val dx=x-cx;val dy=y-cy;val d=hypot(dx,dy);if(d<=r||d==0f){jx=(dx/r).coerceIn(-1f,1f);jy=(dy/r).coerceIn(-1f,1f)}else{jx=dx/d;jy=dy/d}}
 }
